313	    this.#documents.set(document.id, document);
314	    return structuredClone(document);
315	  }
316	
317	  get(id) {
318	    const document = this.#documents.get(id);
319	    return document ? structuredClone(document) : null;
320	  }
321	
322	  remove(id) {
323	    return this.#documents.delete(id);
324	  }
325	
326	  list() {
327	    return [...this.#documents.values()].map((document) => structuredClone(document)).sort((a, b) => a.id.localeCompare(b.id));
328	  }
329	
330	  search(query) {
331	    const needle = String(query).trim().toLowerCase();
332	    if (!needle) return [];
333	    return this.list().filter((document) => [document.title, document.body, ...document.tags].some((value) => value.toLowerCase().includes(needle)));
334	  }
335	
336	  links(id) {
337	    const document = this.#documents.get(id);
338	    if (!document) return null;
339	    const outgoing = [...new Set(linksFrom(document.body))].sort();
340	    const incoming = [...this.#documents.values()]
341	      .filter((candidate) => candidate.id !== id && linksFrom(candidate.body).includes(id))
342	      .map((candidate) => candidate.id)
343	      .sort();
344	    return { outgoing, incoming };
345	  }
