458	      }
459	      assertTitleFree(candidate, document.title);
460	      candidate.add(document);
461	      if (nextLedger) nextLedger.record(document.id, 'create', candidate.get(document.id));
462	    });
463	    sendJson(res, 201, snapshot, `"${snapshot.checksum}"`);
464	  }
465	
466	  async function replaceDocument(req, res, id) {
467	    const bytes = await readBody(req);
468	    requireIfMatch(req);
469	    const document = validateDocument(parseJson(decodeJsonBody(bytes)));
470	    if (document.id !== id) {
