645	    if (result.snapshot.checksum === currentSnapshot.checksum) {
646	      return { snapshot: currentSnapshot, changedIds: [] };
647	    }
648	
649	    const candidate = new Workspace();
650	    for (const document of result.snapshot.documents) candidate.add(document);
651	    const nextLedger = ledger ? ledger.clone() : null;
652	    for (const id of result.changedIds) {
653	      if (!nextLedger) break;
654	      const stored = candidate.get(id);
655	      if (stored) {
656	        // A previously-deleted id that reappears continues its chain with a
657	        // create; a changed live document gets a replace.
658	        const action = current.get(id) ? 'replace' : 'create';
659	        nextLedger.record(id, action, stored);
660	      } else {
661	        nextLedger.record(id, 'delete', null);
662	      }
663	    }
664	
665	    if (dryRun) {
666	      return { snapshot: candidate.exportJSON(), changedIds: result.changedIds };
667	    }
668	
669	    const snapshot = candidate.exportJSON();
670	    save(snapshot, nextLedger ? nextLedger.exportJSON(snapshot.checksum) : null);
671	    current = candidate;
672	    ledger = nextLedger;
673	    return { snapshot, changedIds: result.changedIds };
674	  }
675	
676	  async function reconcile(req, res) {
677	    const bytes = await readBody(req);
678	    requireIfMatch(req);
679	    const { base, incoming, dryRun } = validateReconcileRequest(parseJson(decodeJsonBody(bytes)));
680	    try {
681	      const snapshot = commitReconcile(base, incoming, dryRun).snapshot;
682	      sendJson(res, 200, snapshot, `"${snapshot.checksum}"`);
683	    } catch (error) {
