685	      // failures as INVALID_SNAPSHOT rather than an internal error. Save
686	      // failures keep their 500/IO_ERROR semantics.
687	      if (error instanceof SnapshotError && error.code === 'INVALID_SNAPSHOT') {
688	        throw new HttpError(400, 'INVALID_SNAPSHOT', error.message);
689	      }
690	      throw error;
691	    }
692	  }
693	
694	  async function handle(req, res) {
695	    const url = new URL(req.url, 'http://127.0.0.1');
696	    const segments = url.pathname.split('/').filter(Boolean).map(decodeURIComponent);
697	    const [resource, id, relation] = segments;
698	
699	    if (resource === 'documents' && segments.length === 1) {
700	      if (req.method === 'GET') {
701	        sendJson(res, 200, current.list(), currentEtag());
702	        return;
703	      }
704	      if (req.method === 'POST') {
705	        await createDocument(req, res);
706	        return;
707	      }
708	    } else if (resource === 'documents' && segments.length === 2) {
709	      if (req.method === 'GET') {
710	        const document = current.get(id);
711	        if (!document) throw new HttpError(404, 'NOT_FOUND', `document not found: ${id}`);
